import{_ as e,o,c as l,a2 as r}from"./chunks/framework.BWuWLRhz.js";const h=JSON.parse('{"title":"クイックパネル設定","description":"","frontmatter":{},"headers":[{"level":2,"title":"1. コア機能とメインスイッチ","slug":"_1-コア機能とメインスイッチ","link":"#_1-コア機能とメインスイッチ","children":[]},{"level":2,"title":"2. ワークスペース（Workspaces）","slug":"_2-ワークスペース-workspaces","link":"#_2-ワークスペース-workspaces","children":[]},{"level":2,"title":"3. ソース設定（Sources）","slug":"_3-ソース設定-sources","link":"#_3-ソース設定-sources","children":[]},{"level":2,"title":"4. プラグイン動的タブ（Plugin Tabs）","slug":"_4-プラグイン動的タブ-plugin-tabs","link":"#_4-プラグイン動的タブ-plugin-tabs","children":[]},{"level":2,"title":"5. アプリ連携と専用ブラックリスト","slug":"_5-アプリ連携と専用ブラックリスト","link":"#_5-アプリ連携と専用ブラックリスト","children":[]},{"level":2,"title":"6. パネルの操作ガイド","slug":"_6-パネルの操作ガイド","link":"#_6-パネルの操作ガイド","children":[]}],"relativePath":"ja-JP/user-guide/settings/quick-panel.md","filePath":"ja-JP/user-guide/settings/quick-panel.md","lastUpdated":1791112464000}'),s={name:"ja-JP/user-guide/settings/quick-panel.md"};function n(i,t,a,g,d,c){return o(),l("div",null,[...t[0]||(t[0]=[r('<h1 id="クイックパネル設定" tabindex="-1">クイックパネル設定 <a class="header-anchor" href="#クイックパネル設定" aria-label="Permalink to &quot;クイックパネル設定&quot;">​</a></h1><p><strong>クイックパネル（Quick Panel）</strong> は、頻繁に使用するファイルの呼び出し、プロジェクトのコンテキスト管理、デスクトップ上でのドラッグ＆ドロップ操作のために設計されたフローティングワークスペースです。ホットキーを押すとアクティブウィンドウの右下に吸着表示され、作業中の画面を離れずにファイルを参照・整理できます。</p><h2 id="_1-コア機能とメインスイッチ" tabindex="-1">1. コア機能とメインスイッチ <a class="header-anchor" href="#_1-コア機能とメインスイッチ" aria-label="Permalink to &quot;1. コア機能とメインスイッチ&quot;">​</a></h2><ul><li><strong>クイックパネルを有効化</strong>：全体の有効化スイッチ。無効にするとホットキーは反応しなくなります。</li><li><strong>呼び出しホットキー</strong>：既定は <strong><code>Ctrl+F2</code></strong>（<a href="./hotkeys-page.html"><strong>設定 → ホットキー</strong></a> で変更可能）。</li><li><strong>スマートドッキングとサイズ制御</strong>：親ウィンドウの幅・高さのそれぞれ 1/2 のサイズで表示されます（視認性と操作性を保つため最小サイズは <code>280 × 200px</code> に制限）。Lertaro のウィンドウがアクティブな場合は誤動作防止のためホットキーは無視され、パネルが開いている状態で同じホットキーを押すと閉じます。</li></ul><h2 id="_2-ワークスペース-workspaces" tabindex="-1">2. ワークスペース（Workspaces） <a class="header-anchor" href="#_2-ワークスペース-workspaces" aria-label="Permalink to &quot;2. ワークスペース（Workspaces）&quot;">​</a></h2><p>プロジェクトやタスクごとにフォルダーの組み合わせを整理できます。</p><ul><li><strong>ワークスペース管理</strong>：左側の一覧で <strong>新規作成</strong>、<strong>複製</strong>、<strong>削除</strong> を行え、ドラッグでタブバー上の表示順序を並び替えられます。</li><li><strong>プロパティ</strong>： <ul><li><strong>名前</strong>：タブに表示されるテキスト（空欄の場合は言語設定に応じた既定名になります）。</li><li><strong>有効スイッチ</strong>：タブバーに表示するかどうかを制御します。パネル上でタブの <strong>×</strong> ボタンを押して非表示にした場合も、ここで再度有効化できます。</li></ul></li></ul><p>選択したワークスペースは、右側の <strong>ソース</strong> と <strong>アプリケーション</strong> の 2 つのタブで設定します。</p><h2 id="_3-ソース設定-sources" tabindex="-1">3. ソース設定（Sources） <a class="header-anchor" href="#_3-ソース設定-sources" aria-label="Permalink to &quot;3. ソース設定（Sources）&quot;">​</a></h2><p>ワークスペース内の独立したフォルダーグループを定義します。</p><ul><li><strong>フォルダーを追加</strong>：対象となる物理ディレクトリを選択します。</li><li><strong>表示モード（Display Mode）</strong>： <ul><li><strong>最近変更されたファイル</strong> —— インメモリインデックスからミリ秒未満で最近更新されたファイルを抽出（新しい順）。</li><li><strong>すべてのコンテンツ</strong> —— すべてのファイルを表示し、更新日時の降順または名前で並べ替えられます（名前順は定番ファイルのショートカットバーとして利用できます）。</li><li><strong>フォルダーのみ</strong> —— ディレクトリだけを一覧表示。</li><li><strong>ファイルのみ</strong> —— ファイルだけを一覧表示。</li></ul></li><li><strong>サブフォルダーを含める</strong>：配下のファイルを再帰的に含めます。</li><li><strong>ドロップされたファイルを受け入れる</strong>：有効にすると、外部からファイルやフォルダー、Web 画像をこのグループにドラッグ＆ドロップしてコピーできます（Windows 標準のコピー機能を使用し、衝突確認や取り消しに対応）。</li><li><strong>フィルタールール</strong>：ワイルドカードまたは検索構文の <code>@</code> フィルターで表示する拡張子を限定（例: <code>*.mp4;*.mkv</code>、<code>*.lnk;:@doc;:@img</code>、<code>*.lnk;:@doc|img</code>）。</li><li><strong>最大表示件数と時間制限</strong>：表示件数の上限（0 で無制限）や、N 分以内に更新されたファイルのみに絞り込む設定。</li><li><strong>詳細リスト vs サムネイルタイル</strong>：グループごとにリスト表示かグリッドタイル表示かを選択可能（タイルは縦横比を維持したまま均等に拡大縮小）。</li></ul><h2 id="_4-プラグイン動的タブ-plugin-tabs" tabindex="-1">4. プラグイン動的タブ（Plugin Tabs） <a class="header-anchor" href="#_4-プラグイン動的タブ-plugin-tabs" aria-label="Permalink to &quot;4. プラグイン動的タブ（Plugin Tabs）&quot;">​</a></h2><p>プラグインが提供する動的リストをクイックパネルに表示できます。CoreExtensions には 5 つの標準タブが含まれています。</p><table tabindex="0"><thead><tr><th style="text-align:left;">プラグインタブ</th><th style="text-align:left;">内容</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>お気に入り</strong></td><td style="text-align:left;">スターを付けた登録アイテム（URL はブラウザーで開きます）。</td></tr><tr><td style="text-align:left;"><strong>履歴</strong></td><td style="text-align:left;">Lertaro 経由で開いた最近のアイテムやアプリ。</td></tr><tr><td style="text-align:left;"><strong>Windows 履歴</strong></td><td style="text-align:left;">Windows の「最近使った項目」を実ファイルとして展開。</td></tr><tr><td style="text-align:left;"><strong>前回のフォルダー</strong></td><td style="text-align:left;">エクスプローラーやダイアログで直前に開いていたフォルダーを追跡。</td></tr><tr><td style="text-align:left;"><strong>最近のファイル</strong></td><td style="text-align:left;">インデックスを利用して設定済みフォルダー内の最新ファイルを一覧表示。</td></tr></tbody></table><p>各タブの有効/無効や、リスト/タイルの初期表示形式を個別に設定できます。</p><h2 id="_5-アプリ連携と専用ブラックリスト" tabindex="-1">5. アプリ連携と専用ブラックリスト <a class="header-anchor" href="#_5-アプリ連携と専用ブラックリスト" aria-label="Permalink to &quot;5. アプリ連携と専用ブラックリスト&quot;">​</a></h2><ul><li><strong>アプリケーション連携（Applications）</strong>：特定のプロセス名（例: <code>chrome.exe</code> や <code>devenv.exe</code>）を登録すると、そのアプリ上でクイックパネルを呼び出した際に該当するワークスペースが自動で開きます。</li><li><strong>クイックパネル専用ブラックリスト</strong>：パネルの表示を抑制したいアプリを登録します。グローバルブラックリストに<strong>上乗せ</strong>して適用されます。</li></ul><h2 id="_6-パネルの操作ガイド" tabindex="-1">6. パネルの操作ガイド <a class="header-anchor" href="#_6-パネルの操作ガイド" aria-label="Permalink to &quot;6. パネルの操作ガイド&quot;">​</a></h2><ul><li><strong>リアルタイムあいまい絞り込み</strong>：右上の検索ボックスであいまい一致とピンイン検索による絞り込みが可能。絞り込むのは<strong>名前だけ</strong>で、一覧の並び順が変わることはありません。項目がすべて外れたグループは表示されなくなりますが、タブは残ります。<code>Escape</code> はまず絞り込みをクリアし、<strong>2 回目</strong>の <code>Escape</code> ではじめてパネルが閉じます。</li><li><strong>キーボードナビゲーション</strong>：上下キーでグループをまたいで選択移動し、<code>Enter</code> で実行するとパネルは開いたままです。この移動は<strong>ループしません</strong>。最初と最後に見えている項目が明確な終点となり、空のグループは飛ばされ、まだ何も選択していない状態では <code>↑</code> / <code>↓</code> のどちらも先頭項目に移動します。タイル表示では 4 つの矢印キーが見た目のグリッド上を動きます。<code>←</code> / <code>→</code> は読む順序で行の境界をまたぎ、<code>↑</code> / <code>↓</code> は列を維持します。</li><li><strong>タブ切り替え</strong>：<code>Ctrl</code> + <code>1</code>–<code>9</code> で各タブ間をすばやく切り替え。</li><li><strong>QuickLook プレビューとピン留め</strong>：項目を選択して <code>Alt+P</code> でプレビューを表示、<code>Ctrl+T</code> またはヘッダーのピンボタンでフォーカス喪失時も閉じないように固定。</li><li><strong>フォーカスの行先</strong>：呼び出すとキャレットは絞り込みボックスに入り、先頭の項目がすでに選択された状態になります。そのまま入力して絞り込めます。ボックスがフォーカスを持っている間、プラグインのアクションホットキーは意図的に身を引きます。ここでは <code>Ctrl+A</code> と <code>Ctrl+C</code> はファイル操作ではなくテキスト編集を意味します。</li><li><strong>アクションフライアウト</strong>：右クリックを<strong>離したとき</strong>（押したときではない）に、メインウィンドウと同じアクションフライアウトがカーソル位置に開きます。未選択の行を右クリックすれば、その行に対して作用します。フライアウトはそのあと <code>↑ ↓ ← →</code>、<code>Enter</code>、<code>Space</code>、<code>Escape</code> を受け持ちます。キーハンドラをパネルにぶら下げる形になっているため、フライアウトが開いている間は、通常ならパネルを閉じるところの外側クリックが無視されます。</li><li><strong>行に対するマウス操作</strong>：左ダブルクリックで開きます。右ダブルクリックはフライアウトを開き直すだけで、起動することはありません。中クリックでプレビューを開閉し、行にホバーすると選択が動きます。</li><li><strong>パネルの移動</strong>：ポインターがヘッダーに近づくとドラッグ用の帯が表示され、そこをドラッグするとパネルが移動します。ドラッグ中でもパネルは閉じられません（エクスプローラーからのドラッグアウトがパネル内に落ちるのはそのためです）。</li><li><strong>外側をクリックしたとき</strong>：フォーカスが離れて約 200 ms 後にパネルは隠れます。ただし、パネルをドラッグしていたとき、ピン留めされているとき、アクションフライアウトが開いているとき、そしてパネルが開いたプレビューがフォアグラウンドを保っているときは立ち退きません。自分のプレビュー側をクリックするのは、外側をクリックしたことには当たりません。</li><li><strong>選択の編集</strong>：グループ内の余白をクリックすると、<code>Ctrl</code> や <code>Shift</code> を押していない限り<strong>すべての</strong>グループの選択が同時に解除されます。ラバーバンドのドラッグは自分のグループ内でのみ選択し、<code>Ctrl</code> を併用すれば追加選択になります。あるグループで始めたドラッグは別のグループへ届くことはありません。</li><li><strong>ファイルのドロップを受け入れる</strong>：<strong>Lertaro の内で始まった</strong>ドラッグは受け付けられません。途中でやめたドラッグアウトが余計なコピーになることはないということです。クリックアウトでパネルが閉じるため、エクスプローラーからファイルをドラッグインできるのはパネルが<strong>ピン留めされている間だけ</strong>です。ドロップは常にコピーとなり、移動になることはありません。</li><li><strong>グループヘッダー</strong>：ヘッダーの名前、パス、ルールの行をクリックするとグループの折りたたみと展開が切り替わります。ソートと表示はその横にある別々のボタンです。並び替え・表示モード・折りたたみ状態はセッション単位で、タブの順序とタブを閉じた操作は永続します。</li></ul>',19)])])}const p=e(s,[["render",n]]);export{h as __pageData,p as default};
